// TH14 v1.00b Stage 3 道中 第 6 波
// 源：st03.ecl.txt:603-637 MainSub03（入口）；ECir00 8-31、ECir00_at 33-87（闭包）
// 源起点为本卡帧 0；卡内 120 帧开场缓冲后执行源排程（st03.ecl.txt:605 wait(60) 起）。
const TIME_LIMIT: int = 2324;
const OPENING_BUFFER: int = 120;

// ECir00_at：每只敌在出生 +40 帧启动的一串直线激光。
// 源逐条 etNew/etSprite(20,3)/etAngle(A,0)/etSpeed(v,v)/laserNew(0,L,0,14)/laserOn，
// 每条后 wait(gap)；A 从 F0 起每发加 F1（st03.ecl.txt:70-85）。
async sub fire_fan(a0: angle, delta: angle) {
    var rank: int = global(GVAR_RANK);
    var count: int = 11;
    var gap: int = 7;
    var speed: fx = 2.7fx;
    var off: fx = 12.8fx;    // Line 判定近端 L/10，L=128
    var rod: fx = 102.4fx;   // Line 判定长度 0.8L
    if rank == 1 {
        count = 16; gap = 5; speed = 3fx;
    } else if rank == 2 {
        count = 20; gap = 4; speed = 4fx;
        off = 14.4fx; rod = 115.2fx;   // L=144
    } else if rank == 3 {
        count = 24; gap = 4; speed = 5fx;
        off = 16fx; rod = 128fx;       // L=160
    }
    var a: angle = a0;
    for k in 0..count {
        // 源激光宽 14<32，Line 半高 14/4，目标完整判定宽 7；颜色取 etSprite 色 3。
        var h: int = laser(3, $self_x, $self_y, a, 0fx, 7fx, 0, 9999, 0);
        if h >= 0 {
            lz_start(h, off);
            lz_speed(h, speed, rod);   // 沿射线长出并飞出，start>640 自动回收
        }
        a = a + delta;
        wait(gap);
    }
}

// ECir00：源 8-31。框、朝向自机的两段速度与循环存活。
async sub ecir00(group: int, start: angle, sign: int) {
    set_invuln(65535);
    set_hurtbox(12fx);   // setHurtbox(24,24) 普通圆形取第一值×0.5
    set_hitbox(8fx);     // setHitbox(16,16) 普通圆形取第一值×0.5

    // F1 的各档值（diffF，st03.ecl.txt:607/614/623）；group 对应源三组参数。
    var mag: angle = 24deg;
    var rank: int = global(GVAR_RANK);
    if group == 0 {
        if rank == 0 { mag = 24deg; }
        else if rank == 1 { mag = 20deg; }
        else if rank == 2 { mag = 17deg; }
        else { mag = 28deg; }
    } else if group == 1 {
        if rank == 0 { mag = 23deg; }
        else if rank == 1 { mag = 19deg; }
        else if rank == 2 { mag = 16deg; }
        else { mag = 26deg; }
    } else {
        if rank == 0 { mag = 22deg; }
        else if rank == 1 { mag = 18deg; }
        else if rank == 2 { mag = 15deg; }
        else { mag = 24deg; }
    }
    var delta: angle = mag;
    if sign < 0 { delta = (0 - (mag as int)) as angle; }

    move_vel(0, aim_player(), 3fx, EASE_LINEAR);   // moveVel(%ANGLE_PLAYER, 3.0f)
    move_speed(40, 0fx, EASE_QUAD_IN);             // moveSpeedTime(40, 1, 0.0f)
    wait(40);
    spawn fire_fan(start, delta);                  // @ECir00_at(%F0) async
    wait(60);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);   // moveVel(%ANGLE_PLAYER, 0.0f)
    move_speed(120, 2fx, EASE_QUAD_IN);            // moveSpeedTime(120, 1, 2.0f)
    loop { wait(1000); }                           // 源 ECir00_424/444 的 1000 帧循环
}

// MainSub03：st03.ecl.txt:603-637 的完整排程。
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(60);
    // 60：x=±128，F0=π / 0，F1=∓group0（源 607-611）
    _ = spawn_enemy(128fx, -32fx, 180, 1, 1000, 0, ecir00(0, 180deg, -1));
    _ = spawn_enemy(-128fx, -32fx, 180, 1, 1000, 0, ecir00(0, 0deg, 1));
    wait(120);
    // 180：x=64，group1（源 614-615）
    _ = spawn_enemy(64fx, -32fx, 180, 1, 1000, 0, ecir00(1, 180deg, -1));
    wait(60);
    // 240：x=-64，group1 取反（源 617-619）
    _ = spawn_enemy(-64fx, -32fx, 180, 1, 1000, 0, ecir00(1, 0deg, 1));
    wait(60);
    // 300：x=160，group2（源 621-624）
    _ = spawn_enemy(160fx, -32fx, 180, 1, 1000, 0, ecir00(2, 180deg, -1));
    wait(60);
    // 360：x=-160，group2 取反（源 626-628）
    _ = spawn_enemy(-160fx, -32fx, 180, 1, 1000, 0, ecir00(2, 0deg, 1));
    wait(60);
    // 420：x=±128，group0（源 630-635）
    _ = spawn_enemy(128fx, -32fx, 180, 1, 1000, 0, ecir00(0, 180deg, -1));
    _ = spawn_enemy(-128fx, -32fx, 180, 1, 1000, 0, ecir00(0, 0deg, 1));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
